import {NextResponse} from "next/server";
import {CheckTime} from "@/app/api/isApplication/checkTime";
import {CheckTeamAmount} from "@/app/api/isApplication/checkTeamAmount";
import {IsIgnore} from "@/app/api/isApplication/isIgnore";

export async function POST() {
    const checkTime = await CheckTime();
    const checkTeamAmount = await CheckTeamAmount();
    const isIgnore = await IsIgnore();

    if(isIgnore || (checkTime && checkTeamAmount)){
        NextResponse.json({canRegister: "YES"})
    }else{
        return NextResponse.json({ canRegister: "NO" });
    }
}

import {NextResponse} from "next/server";
import {CheckTime} from "@/app/api/isApplication/checkTime";
import {CheckTeamAmount} from "@/app/api/isApplication/checkTeamAmount";
import {IsIgnore} from "@/app/api/isApplication/isIgnore";

export async function POST() {
    const checkTime = await CheckTime();
    const checkTeamAmount = await CheckTeamAmount();
    const isIgnore = await IsIgnore();

    if(isIgnore || (checkTime && checkTeamAmount)){
        return NextResponse.json({canRegister: "YES"});
    }else{
        return NextResponse.json({ canRegister: "NO" });
    }
}

import {NextRequest, NextResponse} from "next/server";
import {Player} from "@/util/Player";
import {GoogleSpreadsheetService} from "@/util/SpreadSheetService";
import {REGISTER_HEADER} from "@/util/SheetHeader";
import {Readable} from "node:stream";

export async function POST(req: NextRequest) {
    try {
        const { REGISTER_SHEET_ID } = process.env;
        const DRIVE_FOLDER_ID = process.env.DRIVE_FOLDER_ID ?? "";

        const formData = await req.formData();

        //提出期限すぎていないかのチェック

        //テキストデータ
        const teamName = formData.get("teamName") as string;
        const teamNickName = formData.get("teamNickname") as string;
        const contact = formData.get("contact") as string;
        const teamLogo = formData.get("teamLogo") as File;
        const ign1 = formData.get("player1") as string;
        const ign2 = formData.get("player2") as string;
        const ign3 = formData.get("player3") as string;
        const ign4 = formData.get("player4") as string;
        const ign5 = formData.get("player5") as string;
        const ign6 = formData.get("player6") as string;
        const ign7 = formData.get("player7") as string;
        const ign8 = formData.get("player8") as string;
        const ign9 = formData.get("player9") as string;
        const ign10 = formData.get("player10") as string;
        const comment = formData.get("comment") as string;

        //プレイヤーの取得
        const players = await Promise.all([
            new Player(ign1).getInstance(),
            new Player(ign2).getInstance(),
            new Player(ign3).getInstance(),
            new Player(ign4).getInstance(),
            new Player(ign5).getInstance(),
            new Player(ign6).getInstance(),
            new Player(ign7).getInstance(),
            new Player(ign8).getInstance(),
            new Player(ign9).getInstance(),
            new Player(ign10).getInstance()
        ]);

        const teamMemberWinRate = players
            .map(p => p.getWinRate())
            .filter((wr): wr is number => typeof wr === 'number');
        const teamWinRate = teamMemberWinRate
            .reduce(function(prev, current, i ,arr){
                return prev+current;
            }) / teamMemberWinRate.length;

        const sheetRows: (string[] | Record<string, string | number | boolean>)[] = [
            {
                Type: "TeamInfo",
                IGN: teamNickName,
                ID: teamName,
                WinRate: teamWinRate,
                Contact: contact,
                Comment: comment
            }
        ];
        for(let i = 0; i<players.length; i++){
            sheetRows.push(
                {
                    Type: `player${i+1}`,
                    IGN: players[i].getIgn(),
                    ID: players[i].getUid() ?? "undefined",
                    WinRate: players[i].getWinRate() ?? "undefined",
                }
            );
        }

        //spreadsheetへの情報書き込み
        const spreadSheet = new GoogleSpreadsheetService(REGISTER_SHEET_ID ?? "");
        await spreadSheet.addSheet(teamNickName, REGISTER_HEADER);
        await spreadSheet.addRows(teamNickName,sheetRows);


        //画像に(チームロゴ)関する処理
        const fs = require('fs');
        const {GoogleAuth} = require('google-auth-library');
        const {google} = require('googleapis');

        // ファイルを ArrayBuffer として取得し、Buffer に変換
        const arrayBuffer = await teamLogo.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Buffer から Node.js のストリームを作成
        const nodeStream = Readable.from(buffer);

        //ファイル名を作成
        const lastDotIndex = teamLogo.name.lastIndexOf(".");
        const fileName = teamNickName + (lastDotIndex !== -1 ? teamLogo.name.slice(lastDotIndex) : "");

        // Get credentials and build service
        const auth = new GoogleAuth({
            scopes: 'https://www.googleapis.com/auth/drive',
        });
        const drive = google.drive({version: 'v3', auth});
        const fileMetadata = {
            name: fileName,
            parents: [DRIVE_FOLDER_ID],
        };
        // ファイルのアップロード
        const uploadResponse = await drive.files.create({
            requestBody: fileMetadata,
            media: {
                mimeType: teamLogo.type,
                body: nodeStream,
            },
            fields: "id",
        });

        return NextResponse.json({ message: "ok" });
    } catch (error: any) {
        // エラー時はエラーメッセージを返す
        return NextResponse.json(
            { message: error?.message ?? "登録処理中にエラーが発生しました" },
            { status: 400 }
        );
    }
}

import {NextRequest, NextResponse} from "next/server";
import {Player} from "@/util/Player";
import {GoogleSpreadsheetService} from "@/util/SpreadSheetService";
import {REGISTER_HEADER} from "@/util/SheetHeader";
import {Readable} from "node:stream";

export async function POST(req: NextRequest) {
    try {
        const { REGISTER_SHEET_ID } = process.env;
        const DRIVE_FOLDER_ID = process.env.DRIVE_FOLDER_ID ?? "";

        const formData = await req.formData();

        //提出期限すぎていないかのチェック
        const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || process.env.VERCEL_URL
            ? `https://${process.env.VERCEL_URL}`
            : "http://localhost:3000";
        const isAppRes = await fetch(`${baseUrl}/api/isApplication`, { method: "POST" });
        const isAppJson = await isAppRes.json();
        if (isAppJson?.canRegister !== "YES") {
            return NextResponse.json(
                { message: "募集期間が過ぎています" },
                { status: 400 }
            );
        }

        //テキストデータ
        const teamName = formData.get("teamName") as string;
        const teamNickName = formData.get("teamNickname") as string;
        const contact = formData.get("contact") as string;
        const teamLogo = formData.get("teamLogo") as File;
        const ign1 = formData.get("player1") as string;
        const ign2 = formData.get("player2") as string;
        const ign3 = formData.get("player3") as string;
        const ign4 = formData.get("player4") as string;
        const ign5 = formData.get("player5") as string;
        const ign6 = formData.get("player6") as string;
        const ign7 = formData.get("player7") as string;
        const ign8 = formData.get("player8") as string;
        const ign9 = formData.get("player9") as string;
        const ign10 = formData.get("player10") as string;
        const comment = formData.get("comment") as string;

        //プレイヤーの取得
        const players = await Promise.all([
            new Player(ign1).getInstance(),
            new Player(ign2).getInstance(),
            new Player(ign3).getInstance(),
            new Player(ign4).getInstance(),
            new Player(ign5).getInstance(),
            new Player(ign6).getInstance(),
            new Player(ign7).getInstance(),
            new Player(ign8).getInstance(),
            new Player(ign9).getInstance(),
            new Player(ign10).getInstance()
        ]);

        const teamMemberWinRate = players
            .map(p => p.getWinRate())
            .filter((wr): wr is number => typeof wr === 'number');
        const teamWinRate = teamMemberWinRate
            .reduce(function(prev, current, i ,arr){
                return prev+current;
            }) / teamMemberWinRate.length;

        const sheetRows: (string[] | Record<string, string | number | boolean>)[] = [
            {
                Type: "TeamInfo",
                IGN: teamNickName,
                ID: teamName,
                WinRate: teamWinRate,
                Contact: contact,
                Comment: comment
            }
        ];
        for(let i = 0; i<players.length; i++){
            sheetRows.push(
                {
                    Type: `player${i+1}`,
                    IGN: players[i].getIgn(),
                    ID: players[i].getUid() ?? "undefined",
                    WinRate: players[i].getWinRate() ?? "undefined",
                }
            );
        }

        //spreadsheetへの情報書き込み
        const spreadSheet = new GoogleSpreadsheetService(REGISTER_SHEET_ID ?? "");
        await spreadSheet.addSheet(teamNickName, REGISTER_HEADER);
        await spreadSheet.addRows(teamNickName,sheetRows);


        //画像に(チームロゴ)関する処理
        const fs = require('fs');
        const {GoogleAuth} = require('google-auth-library');
        const {google} = require('googleapis');

        // ファイルを ArrayBuffer として取得し、Buffer に変換
        const arrayBuffer = await teamLogo.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Buffer から Node.js のストリームを作成
        const nodeStream = Readable.from(buffer);

        //ファイル名を作成
        const lastDotIndex = teamLogo.name.lastIndexOf(".");
        const fileName = teamNickName + (lastDotIndex !== -1 ? teamLogo.name.slice(lastDotIndex) : "");

        // Get credentials and build service
        const auth = new GoogleAuth({
            scopes: 'https://www.googleapis.com/auth/drive',
        });
        const drive = google.drive({version: 'v3', auth});
        const fileMetadata = {
            name: fileName,
            parents: [DRIVE_FOLDER_ID],
        };
        // ファイルのアップロード
        const uploadResponse = await drive.files.create({
            requestBody: fileMetadata,
            media: {
                mimeType: teamLogo.type,
                body: nodeStream,
            },
            fields: "id",
        });

        return NextResponse.json({ message: "ok" });
    } catch (error: any) {
        // エラー時はエラーメッセージを返す
        return NextResponse.json(
            { message: error?.message ?? "登録処理中にエラーが発生しました" },
            { status: 400 }
        );
    }
}

"use client"

import {Box, Button, Heading} from "@chakra-ui/react";
import {FormProvider, useForm} from "react-hook-form";
import {registerType, useRegisterForm} from "@/app/register/components/RegisterForm/useRegisterForm";
import PlayerInput from "@/app/register/components/PlayerInput";
import TeamNameInput from "@/app/register/components/TeamNameInput";
import TeamNickNameInput from "@/app/register/components/TeamNickNameInput";
import TeamLogoInput from "@/app/register/components/TeamLogoInput";
import ContactInput from "@/app/register/components/ContactInput";
import CommentInput from "@/app/register/components/CommentInput";
import {useEffect} from "react";
import {useRouter} from "next/navigation";


export default function RegisterForm(){

    const { onSubmit } = useRegisterForm();

    //react-hook-form Validation
    const methods  = useForm<registerType>({
        mode: "onBlur", // onChange, onBlur, onSubmit, onTouched, allが選択可能
    });
    const {errors,
        isSubmitting,
        isSubmitSuccessful
    } = methods.formState;
    const router = useRouter();

    useEffect(() => {
        if(isSubmitSuccessful){
            router.push('/success')
        }
    }, [isSubmitSuccessful, router]);

    return(
        <FormProvider {...methods}>
            <form onSubmit={methods.handleSubmit(onSubmit)}>

                {/* チーム概要 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        チーム概要
                    </Heading>
                    <div className="mx-auto w-4/5">

                        {/* チーム名 */}
                        <TeamNameInput
                            rhfName={"teamName"}
                            errorMsg={errors.teamName && errors.teamName.message}
                        />

                        {/* チーム略名 */}
                        <TeamNickNameInput
                            rhfName={"teamNickname"}
                            errorMsg={errors.teamNickname && errors.teamNickname.message}
                        />

                        {/* チームロゴ */}
                        <TeamLogoInput
                            rhfName={"teamLogo"}
                            errorMsg={errors.teamLogo && errors.teamLogo.message}
                        />

                        {/* 代表者連絡先 */}
                        <ContactInput
                            rhfName={"contact"}
                            errorMsg={errors.contact && errors.contact.message}
                        />

                    </div>

                </Box>

                {/* 出場者 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        出場者
                    </Heading>
                    <div className="mx-auto w-4/5">

                        {/* 出場者1 */}
                        <PlayerInput
                            label="出場者1 (代表者)"
                            rhfName={"player1"}
                            errorMsg={errors.player1 && errors.player1.message}
                            canEmpty={false}
                        />

                        {/* 出場者2 */}
                        <PlayerInput
                            label="出場者2"
                            rhfName={"player2"}
                            errorMsg={errors.player2 && errors.player2.message}
                            canEmpty={false}
                        />

                        {/* 出場者3 */}
                        <PlayerInput
                            label="出場者3"
                            rhfName={"player3"}
                            errorMsg={errors.player3 && errors.player3.message}
                            canEmpty={false}
                        />

                        {/* 出場者4 */}
                        <PlayerInput
                            label="出場者4"
                            rhfName={"player4"}
                            errorMsg={errors.player4 && errors.player4.message}
                            canEmpty={false}
                        />

                        {/* 出場者5 */}
                        <PlayerInput
                            label="出場者5"
                            rhfName={"player5"}
                            errorMsg={errors.player5 && errors.player5.message}
                            canEmpty={false}
                        />

                        {/* 出場者6 */}
                        <PlayerInput
                            label="出場者6"
                            rhfName={"player6"}
                            errorMsg={errors.player6 && errors.player6.message}
                            canEmpty={false}
                        />

                        {/* 出場者7 */}
                        <PlayerInput
                            label="出場者7"
                            rhfName={"player7"}
                            errorMsg={errors.player7 && errors.player7.message}
                            canEmpty={false}
                        />

                        {/* 出場者8 (補欠) */}
                        <PlayerInput
                            label="出場者8 (補欠)"
                            rhfName={"player8"}
                            errorMsg={errors.player8 && errors.player8.message}
                            canEmpty={true}
                        />

                        {/* 出場者9 (補欠) */}
                        <PlayerInput
                            label="出場者9 (補欠)"
                            rhfName={"player9"}
                            errorMsg={errors.player9 && errors.player9.message}
                            canEmpty={true}
                        />

                        {/* 出場者10 (補欠) */}
                        <PlayerInput
                            label="出場者10 (補欠)"
                            rhfName={"player10"}
                            errorMsg={errors.player10 && errors.player10.message}
                            canEmpty={true}
                        />

                    </div>

                </Box>

                {/* その他ご意見ご質問 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        その他ご意見ご質問
                    </Heading>
                    <div className="mx-auto w-4/5">
                        <CommentInput rhfName={"comment"} errorMsg={errors.comment && errors.comment.message}/>
                    </div>
                </Box>

                {/* 送信ボタン */}
                <Box borderWidth='0px'
                     className="max-w-3xl p-2 mx-auto mt-4 pb-16 flex items-center justify-center">
                    <Button
                        colorScheme='teal'
                        size='lg'
                        type="submit"
                        className="mx-auto"
                        disabled={isSubmitting}
                        isLoading={isSubmitting}
                    >
                        {isSubmitting && <span className="spinner-border spinner-border-sm mr-1"></span>}
                        送信
                    </Button>
                </Box>

            </form>
        </FormProvider>


    )
}

"use client"

import {Box, Button, Heading} from "@chakra-ui/react";
import {FormProvider, useForm} from "react-hook-form";
import {registerType, useRegisterForm} from "@/app/register/components/RegisterForm/useRegisterForm";
import PlayerInput from "@/app/register/components/PlayerInput";
import TeamNameInput from "@/app/register/components/TeamNameInput";
import TeamNickNameInput from "@/app/register/components/TeamNickNameInput";
import TeamLogoInput from "@/app/register/components/TeamLogoInput";
import ContactInput from "@/app/register/components/ContactInput";
import CommentInput from "@/app/register/components/CommentInput";
import {useEffect, useState} from "react";
import {useRouter} from "next/navigation";


export default function RegisterForm(){

    const { onSubmit } = useRegisterForm();

    //react-hook-form Validation
    const methods  = useForm<registerType>({
        mode: "onBlur", // onChange, onBlur, onSubmit, onTouched, allが選択可能
    });
    const {errors,
        isSubmitting,
        isSubmitSuccessful
    } = methods.formState;
    const router = useRouter();
    const [submitError, setSubmitError] = useState<string | null>(null);

    // 送信ハンドラをラップしてエラー時に遷移
    const handleSubmit = async (data: registerType) => {
        try {
            await onSubmit(data);
            router.push('/success');
        } catch (e: any) {
            setSubmitError(e.message || "登録に失敗しました");
            router.push(`/register/error?msg=${encodeURIComponent(e.message || "登録に失敗しました")}`);
        }
    };

    useEffect(() => {
        if(isSubmitSuccessful){
            router.push('/success')
        }
    }, [isSubmitSuccessful, router]);

    return(
        <FormProvider {...methods}>
            <form onSubmit={methods.handleSubmit(handleSubmit)}>

                {/* チーム概要 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        チーム概要
                    </Heading>
                    <div className="mx-auto w-4/5">

                        {/* チーム名 */}
                        <TeamNameInput
                            rhfName={"teamName"}
                            errorMsg={errors.teamName && errors.teamName.message}
                        />

                        {/* チーム略名 */}
                        <TeamNickNameInput
                            rhfName={"teamNickname"}
                            errorMsg={errors.teamNickname && errors.teamNickname.message}
                        />

                        {/* チームロゴ */}
                        <TeamLogoInput
                            rhfName={"teamLogo"}
                            errorMsg={errors.teamLogo && errors.teamLogo.message}
                        />

                        {/* 代表者連絡先 */}
                        <ContactInput
                            rhfName={"contact"}
                            errorMsg={errors.contact && errors.contact.message}
                        />

                    </div>

                </Box>

                {/* 出場者 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        出場者
                    </Heading>
                    <div className="mx-auto w-4/5">

                        {/* 出場者1 */}
                        <PlayerInput
                            label="出場者1 (代表者)"
                            rhfName={"player1"}
                            errorMsg={errors.player1 && errors.player1.message}
                            canEmpty={false}
                        />

                        {/* 出場者2 */}
                        <PlayerInput
                            label="出場者2"
                            rhfName={"player2"}
                            errorMsg={errors.player2 && errors.player2.message}
                            canEmpty={false}
                        />

                        {/* 出場者3 */}
                        <PlayerInput
                            label="出場者3"
                            rhfName={"player3"}
                            errorMsg={errors.player3 && errors.player3.message}
                            canEmpty={false}
                        />

                        {/* 出場者4 */}
                        <PlayerInput
                            label="出場者4"
                            rhfName={"player4"}
                            errorMsg={errors.player4 && errors.player4.message}
                            canEmpty={false}
                        />

                        {/* 出場者5 */}
                        <PlayerInput
                            label="出場者5"
                            rhfName={"player5"}
                            errorMsg={errors.player5 && errors.player5.message}
                            canEmpty={false}
                        />

                        {/* 出場者6 */}
                        <PlayerInput
                            label="出場者6"
                            rhfName={"player6"}
                            errorMsg={errors.player6 && errors.player6.message}
                            canEmpty={false}
                        />

                        {/* 出場者7 */}
                        <PlayerInput
                            label="出場者7"
                            rhfName={"player7"}
                            errorMsg={errors.player7 && errors.player7.message}
                            canEmpty={false}
                        />

                        {/* 出場者8 (補欠) */}
                        <PlayerInput
                            label="出場者8 (補欠)"
                            rhfName={"player8"}
                            errorMsg={errors.player8 && errors.player8.message}
                            canEmpty={true}
                        />

                        {/* 出場者9 (補欠) */}
                        <PlayerInput
                            label="出場者9 (補欠)"
                            rhfName={"player9"}
                            errorMsg={errors.player9 && errors.player9.message}
                            canEmpty={true}
                        />

                        {/* 出場者10 (補欠) */}
                        <PlayerInput
                            label="出場者10 (補欠)"
                            rhfName={"player10"}
                            errorMsg={errors.player10 && errors.player10.message}
                            canEmpty={true}
                        />

                    </div>

                </Box>

                {/* その他ご意見ご質問 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        その他ご意見ご質問
                    </Heading>
                    <div className="mx-auto w-4/5">
                        <CommentInput rhfName={"comment"} errorMsg={errors.comment && errors.comment.message}/>
                    </div>
                </Box>

                {/* 送信ボタン */}
                <Box borderWidth='0px'
                     className="max-w-3xl p-2 mx-auto mt-4 pb-16 flex items-center justify-center">
                    <Button
                        colorScheme='teal'
                        size='lg'
                        type="submit"
                        className="mx-auto"
                        disabled={isSubmitting}
                        isLoading={isSubmitting}
                    >
                        {isSubmitting && <span className="spinner-border spinner-border-sm mr-1"></span>}
                        送信
                    </Button>
                </Box>

            </form>
        </FormProvider>


    )
}

import {object, string} from "yup";
import * as yup from "yup"
import axios from "axios";
import {SubmitHandler} from "react-hook-form";

export const registerSchema = object({
    teamName: string(),
    teamNickname: string(),
    teamLogo: yup
        .mixed<File>()
        .test("fileSize", "ファイルサイズが大きすぎます", (value) => {
            return value && value.size <= 2 * 1024 * 1024; // 2MB制限
        })
    ,
    contact: string(),
    player1: string(),
    player2: string(),
    player3: string(),
    player4: string(),
    player5: string(),
    player6: string(),
    player7: string(),
    player8: string(),
    player9: string(),
    player10: string(),
    comment: string()
})
export type registerType = yup.InferType<typeof registerSchema>;

//送信ボタンの動作
export const onSubmit: SubmitHandler<registerType> = async (formData) => {

    let logo;
    if(formData.teamLogo instanceof FileList){
        logo = formData.teamLogo[0];
    } else if(formData.teamLogo instanceof File){
        logo = formData.teamLogo;
    }

    const sendData = new FormData();
    sendData.append("teamName", formData.teamName ?? "");
    sendData.append("teamNickname", formData.teamNickname ?? "");
    sendData.append("teamLogo", logo ?? new Blob());
    sendData.append("contact", formData.contact ?? "");
    sendData.append("player1", formData.player1 ?? "");
    sendData.append("player2", formData.player2 ?? "");
    sendData.append("player3", formData.player3 ?? "");
    sendData.append("player4", formData.player4 ?? "");
    sendData.append("player5", formData.player5 ?? "");
    sendData.append("player6", formData.player6 ?? "");
    sendData.append("player7", formData.player7 ?? "");
    sendData.append("player8", formData.player8 ?? "");
    sendData.append("player9", formData.player9 ?? "");
    sendData.append("player10", formData.player10 ?? "");
    sendData.append("comment", formData.comment ?? "");
    const res = await axios.post(`/api/register`, sendData,{
        headers: { "Content-Type": "multipart/form-data" },
    });

    return res.data.message as string;
}

export const useRegisterForm = () => {
    return {
        onSubmit
    }
}

import {object, string} from "yup";
import * as yup from "yup"
import axios from "axios";
import {SubmitHandler} from "react-hook-form";

export const registerSchema = object({
    teamName: string(),
    teamNickname: string(),
    teamLogo: yup
        .mixed<File>()
        .test("fileSize", "ファイルサイズが大きすぎます", (value) => {
            return value && value.size <= 2 * 1024 * 1024; // 2MB制限
        })
    ,
    contact: string(),
    player1: string(),
    player2: string(),
    player3: string(),
    player4: string(),
    player5: string(),
    player6: string(),
    player7: string(),
    player8: string(),
    player9: string(),
    player10: string(),
    comment: string()
})
export type registerType = yup.InferType<typeof registerSchema>;

//送信ボタンの動作
export const onSubmit: SubmitHandler<registerType> = async (formData) => {

    let logo;
    if(formData.teamLogo instanceof FileList){
        logo = formData.teamLogo[0];
    } else if(formData.teamLogo instanceof File){
        logo = formData.teamLogo;
    }

    const sendData = new FormData();
    sendData.append("teamName", formData.teamName ?? "");
    sendData.append("teamNickname", formData.teamNickname ?? "");
    sendData.append("teamLogo", logo ?? new Blob());
    sendData.append("contact", formData.contact ?? "");
    sendData.append("player1", formData.player1 ?? "");
    sendData.append("player2", formData.player2 ?? "");
    sendData.append("player3", formData.player3 ?? "");
    sendData.append("player4", formData.player4 ?? "");
    sendData.append("player5", formData.player5 ?? "");
    sendData.append("player6", formData.player6 ?? "");
    sendData.append("player7", formData.player7 ?? "");
    sendData.append("player8", formData.player8 ?? "");
    sendData.append("player9", formData.player9 ?? "");
    sendData.append("player10", formData.player10 ?? "");
    sendData.append("comment", formData.comment ?? "");
    try {
        const res = await axios.post(`/api/register`, sendData,{
            headers: { "Content-Type": "multipart/form-data" },
        });
        return res.data.message as string;
    } catch (error: any) {
        // エラーメッセージをthrow
        throw new Error(error?.response?.data?.message || "登録に失敗しました");
    }
}

export const useRegisterForm = () => {
    return {
        onSubmit
    }
}

"use client";
import { useSearchParams } from "next/navigation";
import { Box, Heading, Text, Button } from "@chakra-ui/react";
import { useRouter } from "next/navigation";

export default function RegisterErrorPage() {
    const searchParams = useSearchParams();
    const msg = searchParams.get("msg") || "不明なエラーが発生しました";
    const router = useRouter();

    return (
        <div className="text-slate-100 bg-gray-800 min-h-screen">
            <Box m={4} className="max-w-full">
                <Box className="max-w-3xl p-2 mx-auto my-4 text-center">
                    <Heading size="lg" className="mb-4">エラーが発生しました</Heading>
                    <Text color="red.400" className="mb-6">{msg}</Text>
                    <Button colorScheme="teal" onClick={() => router.push("/register")}>
                        フォームに戻る
                    </Button>
                </Box>
            </Box>
        </div>
    );
}

"use client";

import RegisterForm from "@/app/register/components/RegisterForm/RegisterForm";
import {Box, Heading} from "@chakra-ui/react";
import {JdmDiscordLink} from "@/components/JdmDiscordLink";
import { useEffect, useState } from "react";
import axios from "axios";

export default function ContestantRegister(){
    const [status, setStatus] = useState<"loading" | "yes" | "no">("loading");
    const [loadingDots, setLoadingDots] = useState<string>(".");

    useEffect(() => {
        if (status !== "loading") return;
        let count = 1;
        const interval = setInterval(() => {
            setLoadingDots(".".repeat((count % 3) + 1));
            count++;
        }, 300);
        return () => clearInterval(interval);
    }, [status]);

    useEffect(() => {
        let isMounted = true;
        (async () => {
            try {
                const res = await axios.post("/api/isApplication", {});
                if (!isMounted) return;
                if (res.data?.canRegister === "YES") {
                    setStatus("yes");
                } else {
                    setStatus("no");
                }
            } catch {
                if (isMounted) setStatus("no");
            }
        })();
        return () => { isMounted = false; };
    }, []);

    if (status === "loading") {
        return (
            <div className="text-slate-100 bg-gray-800">
                <Box m={4} className="max-w-full">
                    <Box className="max-w-3xl p-2 mx-auto my-4 text-center">
                        読み込み中{loadingDots}
                    </Box>
                </Box>
            </div>
        );
    }

    if (status === "no") {
        return (
            <div className="text-slate-100 bg-gray-800">
                <Box m={4} className="max-w-full">
                    <Box className="max-w-3xl p-2 mx-auto my-4 text-center">
                        現在は募集期間ではありません
                    </Box>
                </Box>
            </div>
        );
    }

    return(
        <div className="text-slate-100 bg-gray-800">
            <Box m={4} className="max-w-full">

                {/* フォーム注意事項 */}
                <Box borderWidth='1px' borderRadius='lg' className="max-w-3xl p-2 mx-auto my-4">
                    <Heading
                        size="lg"
                        className="text-center border-b-2 border-slate-400 mt-2 mx-4">
                        フォーム注意事項
                    </Heading>
                    <p className="break-all mx-4 my-2">・このフォームは、出場チーム1つにつき1つ提出となります。</p>
                    <p className="break-all mx-4 my-2">
                        ・提出後の変更は{<JdmDiscordLink/>}の運営ロールの付いた者への直接DMで受け付けます。
                    </p>
                </Box>

                {/* 送信フォームの中身 */}
                <RegisterForm/>

            </Box>
        </div>
    )
}

